import sys, unittest
sys.path.insert(0, "/tmp/agentdiff-haiku-_7wzaljd/work")
from isodur import parse

D, H, M, Y, W = 86400, 3600, 60, 365 * 86400, 7 * 86400
MO = 30 * 86400

class Valid(unittest.TestCase):
    def check(self, text, expected):
        self.assertAlmostEqual(parse(text), expected, msg=text)
    def test_day(self): self.check("P1D", D)
    def test_time_hour(self): self.check("PT1H", H)
    def test_day_and_time(self): self.check("P1DT2H30M", D + 2 * H + 30 * M)
    def test_fractional_seconds(self): self.check("PT0.5S", 0.5)
    def test_week(self): self.check("P2W", 2 * W)
    def test_year(self): self.check("P1Y", Y)
    def test_month_is_30_days(self): self.check("P1M", MO)
    def test_minute_in_time_is_60s(self): self.check("PT1M", M)
    def test_fraction_minutes(self): self.check("PT1.5M", 90)
    def test_comma_fraction(self): self.check("P0,5D", D / 2)
    def test_comma_seconds(self): self.check("PT1,5S", 1.5)
    def test_fraction_on_last_date_number(self): self.check("P1.5Y", 1.5 * Y)
    def test_full_form(self): self.check("P1Y2M3DT4H5M6S", Y + 2 * MO + 3 * D + 4 * H + 5 * M + 6)
    def test_zero(self): self.check("PT0S", 0)
    def test_returns_float(self): self.assertIsInstance(parse("P1D"), float)

BAD = [
    "", "P", "PT", "P1DT", "PT1HT2M", "P2WT1H", "P2W1D", "P1WT",
    "P1D1Y", "P1Y1Y", "PT1M1H", "PT1S1M", "P1H", "PT1Y", "P1S", "P1DT1H2M3S4",
    "+P1D", "-P1D", "P-1D", "p1d", "Pt1h", " P1D", "P1D ", "P1D\n",
    "P1.5H30M", "PT1.5H0M", "P1.5DT2H", "P1,5,5D", "P1.5.5D",
    "P1.D", "P.5D", "PT.5S", "P1", "PT5", "P1X", "P 1D", "P1DT1H2",
    "P٣D", "P1Y\n", "P1W2W", "P1Y2Y",
]

class Invalid(unittest.TestCase):
    def test_all_invalid_raise(self):
        for text in BAD:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse(text)
    def test_non_string_raises_value_error(self):
        for value in (None, 5, b"P1D"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse(value)

if __name__ == "__main__":
    unittest.main(verbosity=1)
